CREATE TABLE `tradeskill` (
  `Id1` int(10) NOT NULL COMMENT 'Source High ID',
  `Id2` int(10) NOT NULL COMMENT 'Target High ID',
  `MinTarget` int(10) NOT NULL DEFAULT '0' COMMENT 'For things like tier armor where the item must be at max QL to tradeskill. 0 = Any ql',
  `ResultIds` tinytext NOT NULL COMMENT 'Comma-delimited ID pairs',
  `QlRangePercent` int(10) NOT NULL COMMENT '0 = Do not check',
  `DeleteFlag` int(10) NOT NULL COMMENT 'Bit 0 = Delete src, Bit 1 = Delete target',
  `Skill` tinytext NOT NULL COMMENT 'Comma-delimited integers. ME = 125, EE = 126, Tutoring = 141, QFT = 157, WS = 158, PT = 159, NP = 160, CL = 161, Psy = 162, Chem = 163, B&E = 165, Strength = 16',
  `SkillPercent` tinytext NOT NULL COMMENT 'Comma-delimited integers. Skill required in % to build. 2.5x skill = 250',
  `SkillPerBump` tinytext NOT NULL COMMENT 'Comma-delimited integers. Bump by one QL for each one of these values above the requirement. e.g. Player has 650 skill. Item requires 550. This value is 50. Player has 100 extra points or two times this value. Bump by two QLs.',
  `MaxBump` int(10) NOT NULL COMMENT 'Maximum number of one QL bumps allowed',
  `MinXP` int(10) NOT NULL,
  `MaxXP` int(10) NOT NULL,
  `IsImplant` int(10) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

